            { "core.guide.tag", new[]{ "PAVISE // CORE GUIDE", "PAVISE // CORE GUIDE" } },
            { "core.guide.s1.t", new[]{ "多数场景无需调整", "Most setups need no changes" } },
            { "core.guide.s1.d", new[]{ "默认全核。仅在确认调度错误并导致掉帧时手动划分。", "Use all cores by default. Partition only after confirming scheduler placement causes frame drops." } },
            { "core.guide.s2.t", new[]{ "核心数量的下限", "Minimum core count" } },
            { "core.guide.s2.d", new[]{ "建议至少保留 8 个逻辑核心；少于 2 个无法应用。", "Keep at least 8 logical cores; fewer than 2 cannot be applied." } },
            { "core.guide.s3.t", new[]{ "需点击应用才会下发", "Nothing takes effect until you click Apply" } },
            { "core.guide.s3.d", new[]{ "选核后点击应用；对局中立即生效，无需重启游戏。", "Select cores, then click Apply. Changes take effect in-match without restarting the game." } },
            { "core.guide.hy.t", new[]{ "本机为 Intel 混合架构", "This machine is an Intel hybrid architecture" } },
            { "core.guide.hy.d", new[]{ "默认全核。仅在游戏线程误落 E 核并掉帧时改用 P 核；E 核无超线程。", "Use all cores by default. Choose P-cores only if game threads land on E-cores and drop frames; E-cores have no Hyper-Threading." } },
            { "core.guide.x3d.t", new[]{ "本机为 AMD 双 CCD，其中一侧带 3D 缓存", "This machine is an AMD dual-CCD part with 3D cache on one side" } },
            { "core.guide.x3d.d", new[]{ "默认由 AMD 驱动选 CCD；分配错误再手选。少数游戏可试高频 CCD，以 1% Low 为准。", "Let AMD choose the CCD by default; intervene only for wrong placement. A few games may prefer the frequency CCD—compare 1% lows." } },
            { "core.guide.ccd.t", new[]{ "本机为 AMD 多 CCD", "This machine is an AMD multi-CCD part" } },
            { "core.guide.ccd.d", new[]{ "默认全核；卡顿时可试单 CCD，但可用核心减半。勿选半块 CCD。", "Default to all cores. Try one CCD for stutter, but it halves cores. Never select half a CCD." } },
            { "core.guide.smt.t", new[]{ "关闭超线程不等于提升", "Disabling Hyper-Threading is not a free win" } },
            { "core.guide.smt.d", new[]{ "关闭 SMT 会减半线程数，通常负优化；仅供老游戏或已有实测收益时使用。", "Disabling SMT halves thread count and usually hurts. Use only for older games or measured gains." } },
            { "core.guide.judge.t", new[]{ "效果判定方式", "How to judge the effect" } },
            { "core.guide.judge.d", new[]{ "比较同场景的 1% Low 和帧时间毛刺；核心划分通常不提高平均帧。", "Compare 1% lows and frame-time spikes in the same scene; core partitioning rarely raises average FPS." } },
            { "core.guide.s4.t", new[]{ "后台无需手动配置", "Background needs no manual setup" } },
            { "core.guide.s4.d", new[]{ "后台不再限定核心，与游戏共用全部核心，靠优先级让路。", "Background is no longer confined to cores; it shares every core with the game and yields by priority." } },
            { "core.guide.note", new[]{ "仅对局中生效，退场自动还原；不写注册表。", "Applies only during matches and restores automatically; no registry writes." } },
