            { "t.systemauditverdicts.59", new[]{ "　核心分区叠加停泊更易产生帧时间毛刺；Pavise 不修改用户自选方案。", " Core partitioning plus parking increases frame-time spikes. Pavise does not alter user plans." } },
            { "t.systemaudit.3", new[]{ "仅检测到核显，显卡深度调优不适用；后台压制、核心绑定和电源计划仍有效。", "Only integrated graphics was detected, so deep GPU tuning is unavailable; background suppression, core binding, and power plans still work." } },
            { "t.systemaudit.4", new[]{ "已检测到独立显卡。显卡页的驱动项是否可用，取决于下方两项接口检测结果。", "A discrete GPU is present. Whether the driver items on the Graphics page are usable depends on the two interface checks below." } },
            { "gm.poweryield", new[]{ "对局功耗让路", "Power budget yield" } },
            { "gm.poweryield.sub", new[]{ "笔记本对局中显卡吃满而处理器有余量时，把共享功耗预算让给显卡。一局只判一次，省不出功耗立即退回。", "On laptops, when the GPU is saturated and the CPU has headroom, yield shared power budget to the GPU. Decided once per match and reverted at once if no power is freed." } },
            { "gm.poweryield.desktop", new[]{ "台式机没有 CPU 与显卡共享的功耗预算，此项不适用。", "Desktops have no shared CPU/GPU power budget, so this does not apply." } },
            { "gm.poweryield.nowatt", new[]{ "本机读不到处理器功耗，无法验证是否真的让出预算，因此不参与。", "Processor power is unreadable on this machine, so the yield cannot be verified and will not run." } },
            { "gm.poweryield.fused", new[]{ "本机验证过没有收益，已停止尝试。重新打开此开关会再验一次。", "This machine measured no benefit and stopped trying. Turning the switch on again re-runs the check." } },
            { "poweryield.warn", new[]{ "这是实验项。对局中会临时抬高处理器能效偏好，让出功耗预算给显卡，退出对局即还原。\r\n\r\n开启后程序会自己验证：封装功耗没有真的下降，或者显卡利用率反而掉了，就立刻退回并记住这台机器不再尝试。\r\n\r\n只在笔记本、插电、专注档、且使用托管电源方案时参与。", "This is experimental. During a match it temporarily raises the processor energy performance preference to yield power budget to the GPU, and restores it when the match ends.\r\n\r\nThe app verifies the result itself: if package power does not actually drop, or GPU utilization falls instead, it reverts at once and remembers not to try again on this machine.\r\n\r\nIt only runs on laptops, on AC power, in the Focus tier, and with the managed power plan." } },
            { "log.poweryield.1", new[]{ "功耗让路 开始观察 GPU 与 CPU 的负载分配", "Power yield: observing how load is split between GPU and CPU" } },
            { "log.poweryield.2", new[]{ "功耗让路 能效偏好改为 {0} GPU {1}% CPU {2}% 封装 {3}W", "Power yield: energy performance preference set to {0}; GPU {1}%, CPU {2}%, package {3}W" } },
            { "log.poweryield.3", new[]{ "功耗让路 写入能效偏好失败 本局放弃 GPU {1}% CPU {2}%", "Power yield: writing the energy performance preference failed; skipped this match. GPU {1}%, CPU {2}%" } },
            { "log.poweryield.4", new[]{ "功耗让路 验证不通过 已退回并记住这台机器不再尝试", "Power yield: verification failed; reverted and this machine will not try again" } },
            { "log.poweryield.5", new[]{ "功耗让路 能效偏好已还原", "Power yield: the energy performance preference was restored" } },
            { "log.poweryield.6", new[]{ "功耗让路 能效偏好还原失败 下次进入托管方案会重写", "Power yield: restoring the energy performance preference failed; the managed plan rewrites it next time" } },
            { "log.poweryield.7", new[]{ "功耗让路 验证通过 本局保持", "Power yield: verification passed; kept for this match" } },
